#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
#include <chrono>
#include <random>
using namespace std;

struct Res { int ways, sum; Res() : ways(0), sum(0) {} Res(int w, int s) : ways(w), sum(s) {} };

int n_components, n_people, mod_value;
vector<vector<int>> C;

int calcSum(int a, int b) { return (a + b) * (b - a + 1) / 2; }

vector<bool> visited2;
vector<Res> memo2;

Res compute2(int n) {
    if (n == 1) return Res(2, 0);
    if (visited2[n]) return memo2[n];
    Res res(0, 0);
    for (int i = 0; i < n; ++i) {
        int leftCount = i, rightCount = n - i - 1;
        Res leftRes = (leftCount == 0) ? Res(1, 0) : compute2(leftCount);
        Res rightRes = (rightCount == 0) ? Res(1, 0) : compute2(rightCount);
        int ways = (leftCount + 1) + (rightCount + 1);
        int sumAdd = calcSum(0, leftCount) + calcSum(0, rightCount);
        int mlt = C[leftCount + rightCount][leftCount];
        res.ways = (res.ways + (long long)leftRes.ways * ways % mod_value * rightRes.ways) % mod_value;
        res.sum = (res.sum + (long long)leftRes.sum * ways % mod_value * rightRes.ways
                   + (long long)leftRes.ways * sumAdd % mod_value * rightRes.ways
                   + (long long)leftRes.ways * ways % mod_value * rightRes.sum) % mod_value;
    }
    visited2[n] = true;
    memo2[n] = res;
    return res;
}

vector<vector<bool>> visited1;
vector<vector<Res>> memo1;

Res compute1(int idx, int cnt) {
    if (n_components - idx == cnt) return compute2(cnt);
    if (visited1[idx][cnt]) return memo1[idx][cnt];
    Res res(0, 0);
    for (int i = idx; i < n_components; ++i) {
        int leftCount = i - idx;
        int rightCount = cnt - leftCount;
        if (rightCount < 0 || rightCount > n_components - i - 1) continue;
        Res leftRes = (i == idx) ? Res(1, 0) : compute2(leftCount);
        Res rightRes = (i + 1 == n_components) ? Res(1, 0) : compute1(i + 1, rightCount);
        int mlt = C[leftCount + rightCount][leftCount];
        res.ways = (res.ways + (long long)leftRes.ways * rightRes.ways % mod_value * mlt) % mod_value;
        res.sum = (res.sum + (long long)leftRes.sum * rightRes.ways % mod_value * mlt
                   + (long long)leftRes.ways * rightRes.sum % mod_value * mlt) % mod_value;
    }
    visited1[idx][cnt] = true;
    memo1[idx][cnt] = res;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int ncomp, npers, MOD;
    cin >> ncomp >> npers >> MOD;
    n_components = ncomp;
    n_people = npers;
    mod_value = MOD;
    C.assign(ncomp + 1, vector<int>(ncomp + 1, 0));
    for (int i = 0; i <= ncomp; ++i) {
        C[i][0] = 1;
        C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }
    visited2.assign(ncomp + 1, false);
    memo2.assign(ncomp + 1, Res());
    visited1.assign(ncomp + 1, vector<bool>(npers + 1, false));
    memo1.assign(ncomp + 1, vector<Res>(npers + 1));
    cout << compute1(0, npers).sum << "\n";
    return 0;
}
